use kassiber_journals::Refusal;
#[inline(never)]
fn prior(
    profile: &str,
    transaction: &str,
    wallet: &str,
    kind: &str,
    asset: &str,
    ordinal: usize,
) -> Result<String, Refusal> {
    kassiber_journals::storage::journal_entry_id(profile, transaction, wallet, kind, asset, ordinal)
}

#[inline(never)]
fn candidate(
    profile: &str,
    transaction: &str,
    wallet: &str,
    kind: &str,
    asset: &str,
    ordinal: usize,
) -> Result<String, Refusal> {
    use std::fmt::Write;
    let options = kassiber_pyjson::Options::new();
    let mut text = String::with_capacity(192);
    text.push('[');
    for value in [
        "kassiber-journal-entry-v1",
        profile,
        transaction,
        wallet,
        kind,
        asset,
    ] {
        if text.len() > 1 {
            text.push(',');
        }
        kassiber_pyjson::dumps_str_into(value, &options, &mut text);
    }
    write!(text, ",{ordinal}]").expect("String formatting");
    use bitcoin_hashes::{sha256, Hash};
    let mut digest = sha256::Hash::hash(text.as_bytes()).to_byte_array();
    digest[6] = (digest[6] & 15) | 128;
    digest[8] = (digest[8] & 63) | 128;
    let mut out = String::with_capacity(36);
    for (index, byte) in digest[..16].iter().copied().enumerate() {
        if [4, 6, 8, 10].contains(&index) { out.push('-'); }
        out.push(b"0123456789abcdef"[usize::from(byte >> 4)] as char);
        out.push(b"0123456789abcdef"[usize::from(byte & 15)] as char);
    }
    Ok(out)
}


fn main() {
 let mode=std::env::args().nth(1).unwrap();
 let inputs:Vec<_>=(0..20_000).map(|i| format!("transaction-{i}-é\\\"🔥")).collect();
 for (index,input) in inputs.iter().enumerate().take(200) { assert_eq!(prior("profile",input,"wallet","buy","BTC",index).unwrap(),candidate("profile",input,"wallet","buy","BTC",index).unwrap()); }
 let function=if mode=="prior" { prior } else { candidate };
 for index in 0..200_000 { std::hint::black_box(function("profile", &inputs[index%inputs.len()],"wallet","buy","BTC",index).unwrap()); }
}

